{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"A landlord may not collect a deposit above 1.5 months' rent (plus the first month's rent at lease inception), may raise the deposit by no more than 10% a year, and must return it with interest, less itemized deductions, within 30 days after the tenancy ends.","key_value":"1.5 months' rent max; 10% yearly increase; 30-day return","coverage_conditions":"Residential rentals in New Jersey, including prepaid last month's rent, which counts toward the deposit limit; not seasonal use or rental of 125 consecutive days or less.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Deposit-holding and interest rules differ for landlords of 10 or more units versus 10 or fewer; seasonal rentals of 125 days or less are exempt"},"exemptions":"Seasonal use or rental of not more than 125 consecutive days by a person whose permanent residence is elsewhere; a landlord is not required to collect a security deposit at all.","penalty":"Tenant may sue for double the amount wrongfully withheld, plus court costs and reasonable attorney's fees.","effective_date":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic-violence lease termination","requirement":"When a tenant ends a lease under the Safe Housing Act, the landlord must make the deposit and interest available to the tenant within 15 business days and, within three business days, notify the tenant in writing where and when to collect it.","key_value":"15 business days","coverage_conditions":"Tenants who terminate a lease under the Safe Housing Act because of domestic violence; does not apply to transient or seasonal rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Applies where a tenant terminates the lease under the Safe Housing Act due to domestic violence; excludes transient or seasonal rentals"},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
